/**
 * File I/O, provenance and code stamps for the validation scripts (scripts/validate/*).
 *
 * These are Node-only helpers. The engine stays pure (no fs, no clock): the scripts read the cached data and the oracle
 * fixtures from disk, call the engine, and write compact JSON to public/data/validation/. Basis: ARCHITECTURE.md §8
 * ("all evidence numbers are regenerated by `npm run validate` into public/data/validation/*.json") and §1.7 (every
 * metric states its data source).
 *
 * Determinism: the JSON outputs carry no wall-clock time. The stamp is a content hash of the code and of every input
 * file, so the same code on the same inputs writes byte-identical files.
 */
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, relative, resolve, sep } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

/** Absolute path of the repository root (this file lives in scripts/validate/lib/). */
export const REPO_ROOT: string = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..')

/** Output directory of every validation JSON (ARCHITECTURE.md §8). */
export const VALIDATION_OUT_DIR: string = join(REPO_ROOT, 'public', 'data', 'validation')

/** Size ceiling of one validation JSON, bytes [ENG: task requirement, keeps the Evidence view light]. */
export const MAX_OUTPUT_BYTES = 1_000_000

/** Repository-relative POSIX path → absolute path. */
export function repoPath(rel: string): string {
  return join(REPO_ROOT, ...rel.split('/'))
}

/** Absolute path → repository-relative POSIX path. */
export function toRepoRel(abs: string): string {
  return relative(REPO_ROOT, abs).split(sep).join('/')
}

/** SHA-256 (hex) of a buffer or string. */
export function sha256(data: string | Buffer): string {
  return createHash('sha256').update(data).digest('hex')
}

/** One input file a validation run read. */
export interface InputFileRecord {
  /** Repository-relative path. */
  path: string
  bytes: number
  sha256: string
  /** True/false when public/data/weather/manifest.json lists the file (checked against its sha256); null otherwise. */
  manifestMatch: boolean | null
}

interface ManifestJson {
  files?: { path?: unknown; sha256?: unknown }[]
}

/**
 * Records every input file a run reads (path, size, SHA-256) and checks weather files against the download manifest
 * (public/data/weather/manifest.json, written by scripts/data/fetch-weather.mjs). Basis: ARCHITECTURE.md §1.7.
 */
export class Provenance {
  private readonly files = new Map<string, InputFileRecord>()
  private manifest: Map<string, string> | null = null

  /** Read and parse a repository-relative JSON file, recording its provenance. */
  readJson(rel: string): unknown {
    const buf = readFileSync(repoPath(rel))
    this.record(rel, buf)
    return JSON.parse(buf.toString('utf8')) as unknown
  }

  /** Record a file that was read by other means. */
  record(rel: string, buf: Buffer): void {
    if (this.files.has(rel)) return
    const hash = sha256(buf)
    const listed = this.manifestSha(rel)
    this.files.set(rel, { path: rel, bytes: buf.length, sha256: hash, manifestMatch: listed === undefined ? null : listed === hash })
  }

  /** Every recorded file, sorted by path. */
  records(): InputFileRecord[] {
    return [...this.files.values()].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
  }

  /** SHA-256 over the sorted "path sha256" lines of every recorded input. */
  inputsSha256(): string {
    return sha256(this.records().map((r) => `${r.path} ${r.sha256}`).join('\n'))
  }

  /** Files whose SHA-256 differs from the manifest (should be empty). */
  manifestMismatches(): string[] {
    return this.records().filter((r) => r.manifestMatch === false).map((r) => r.path)
  }

  private manifestSha(rel: string): string | undefined {
    if (this.manifest === null) {
      this.manifest = new Map()
      const p = repoPath('public/data/weather/manifest.json')
      if (existsSync(p)) {
        const m = JSON.parse(readFileSync(p, 'utf8')) as ManifestJson
        for (const f of m.files ?? []) {
          if (typeof f.path === 'string' && typeof f.sha256 === 'string') this.manifest.set(`public/${f.path}`, f.sha256)
        }
      }
    }
    return this.manifest.get(rel)
  }
}

/** Code and input stamp written into every validation JSON (same idea as sim/types.ts SiteDayResult.stamp). */
export interface CodeStamp {
  /** package.json name@version. */
  package: string
  /** SHA-256 over the code files (CRLF normalised to LF, sorted by path). */
  codeSha256: string
  /** Number of code files hashed. */
  codeFiles: number
  /** SHA-256 over the input files (see {@link Provenance.inputsSha256}). */
  inputsSha256: string
  /** Short human-readable stamp: "zill@0.1.0+code.<12 hex>+inputs.<12 hex>". */
  stamp: string
}

/** Directories whose non-test .ts files make up the code stamp. */
const CODE_DIRS = ['src/engine', 'src/data', 'src/sim', 'scripts/validate', 'scripts/validate/lib'] as const

function listCodeFiles(): string[] {
  const out: string[] = []
  for (const dir of CODE_DIRS) {
    const abs = repoPath(dir)
    if (!existsSync(abs)) continue
    for (const name of readdirSync(abs)) {
      if (name.endsWith('.ts') && !name.endsWith('.test.ts') && !name.endsWith('.d.ts')) out.push(`${dir}/${name}`)
    }
  }
  return out.sort()
}

/**
 * Content stamp of the code that produced a result: package version, a hash of every engine/data/sim/validation source
 * file, and the inputs hash. Deterministic and git-free (the repository is not under version control).
 */
export function codeStamp(inputsSha256: string): CodeStamp {
  const pkg = JSON.parse(readFileSync(repoPath('package.json'), 'utf8')) as { name?: string; version?: string }
  const files = listCodeFiles()
  const h = createHash('sha256')
  for (const f of files) {
    h.update(`${f}\n`)
    h.update(readFileSync(repoPath(f), 'utf8').replace(/\r\n/g, '\n'))
  }
  const codeSha256 = h.digest('hex')
  const name = `${pkg.name ?? 'zill'}@${pkg.version ?? '0.0.0'}`
  return {
    package: name,
    codeSha256,
    codeFiles: files.length,
    inputsSha256,
    stamp: `${name}+code.${codeSha256.slice(0, 12)}+inputs.${inputsSha256.slice(0, 12)}`,
  }
}

/**
 * Write a validation result as compact JSON to public/data/validation/<name>.json.
 * @returns the number of bytes written.
 * @throws Error when the JSON exceeds {@link MAX_OUTPUT_BYTES}.
 */
export function writeValidationJson(name: string, data: unknown): number {
  const text = JSON.stringify(data)
  const bytes = Buffer.byteLength(text, 'utf8')
  if (bytes > MAX_OUTPUT_BYTES) throw new Error(`${name}.json would be ${bytes} bytes (limit ${MAX_OUTPUT_BYTES})`)
  mkdirSync(VALIDATION_OUT_DIR, { recursive: true })
  writeFileSync(join(VALIDATION_OUT_DIR, `${name}.json`), text, 'utf8')
  return bytes
}

/** Read a previously written validation JSON, or null when it does not exist. */
export function readValidationJson(name: string): unknown {
  const p = join(VALIDATION_OUT_DIR, `${name}.json`)
  return existsSync(p) ? (JSON.parse(readFileSync(p, 'utf8')) as unknown) : null
}

/** True when the module with this `import.meta.url` is the process entry point (`tsx scripts/validate/x.ts`). */
export function isMainModule(importMetaUrl: string): boolean {
  const entry = process.argv[1]
  return typeof entry === 'string' && pathToFileURL(resolve(entry)).href === importMetaUrl
}

/** Run `fn`, returning its value and the elapsed wall time in ms (console timing only; never written to JSON). */
export function timed<T>(fn: () => T): { value: T; ms: number } {
  const t0 = performance.now()
  const value = fn()
  return { value, ms: performance.now() - t0 }
}

/** Attribution required by the CC BY 4.0 weather data (Open-Meteo; Copernicus for ERA5) and the METAR provider. */
export const DATA_ATTRIBUTION = {
  weather: 'Weather data by Open-Meteo.com (CC BY 4.0), https://open-meteo.com/',
  era5: 'ERA5: contains modified Copernicus Climate Change Service information',
  ecmwf: 'ECMWF IFS (open data) via Open-Meteo',
  metar: 'METAR: Iowa Environmental Mesonet (IEM), Iowa State University — ASOS/METAR archive',
} as const
